+/**********************************************************************/
+/*   event handling                                                                                                                                         */
+/**********************************************************************/
+
+/*
+ * called eg. after resizing, this function redraws the window 'from
+ * scratch'
+ */
+static void
+redraw()
+{
+  XClearWindow(display, xwindow);
+  if (!doesBs)
+    XFillRectangle(display, bsPixmap, clearGC, 0, 0, xDim + 1, yDim + 1);
+
+  draw_border();
+  setcolor(WHITE);
+  xWin_write_menu();
+  xWin_display_clear();
+
+  curPanel = -1;                /* one panel only */
+  xWin_update(0);
+  xWin_clear();
+
+  write_names();
+
+  if (inCdb) {
+    point = 0;
+    xWin_puts(CDB_PROMPT);
+    cursoron();
+  }
+}
+
+/*
+ * handle the 'standard' events, ie. ConfigureNotify, Expose, (Un)MapNotify
+ */
+static void
+handle_event(event)
+  XEvent *event;
+{
+  int     width, height;
+  static int mapped = 0;
+  int     need_redraw = 0;
+  XEvent  ev;
+
+  switch (event->type) {
+  case Expose:
+    if (doesBs) {
+      if (event->xexpose.count != 0)
+        break;
+      if (mapped)
+        redraw();
+    } else {
+      int     x, y, w, h;
+
+      x = event->xexpose.x;
+      y = event->xexpose.y;
+      w = event->xexpose.width;
+      h = event->xexpose.height;
+
+      XCopyArea(display, bsPixmap, xwindow, writeGC, x, y, w, h, x, y);
+    }
+    break;
+
+  case ConfigureNotify:
+    width = event->xconfigure.width;
+    height = event->xconfigure.height;
+
+    if (width == xDim && height == yDim)
+      return;
+
+    if (!doesBs) {
+      XFreePixmap(display, bsPixmap);
+      bsPixmap = XCreatePixmap(display, xwindow, width, height,
+                               defDepth);
+    }
+    xDim = width;
+    yDim = height;
+    graphio_init();
+
+    if (mapped)
+      redraw();
+    break;
+
+  case MapNotify:
+    mapped = 1;
+    break;
+
+  case UnmapNotify:                /* wait for next map event */
+    for (;;) {
+      XNextEvent(display, &ev);
+      if (ev.type == MapNotify)
+        break;
+
+      if (ev.type == ConfigureNotify) {
+        width = ev.xconfigure.width;
+        height = ev.xconfigure.height;
+
+        if (width != xDim || height != yDim) {
+          if (!doesBs) {
+            XFreePixmap(display, bsPixmap);
+            bsPixmap = XCreatePixmap(display, xwindow, width, height,
+                                     defDepth);
+          }
+          xDim = width;
+          yDim = height;
+          graphio_init();
+          need_redraw = 1;
+        }
+      }
+    }
+    if (need_redraw)
+      redraw();
+    break;
+
+#if 0                                /* debugging only */
+  default:
+    printf("Got unknown event: %d\n", event->type);
+    break;
+#endif
+  }
+}
