+/*
+ * draw a border around the arena
+ */
+static void
+draw_border()
+{
+  int     x = leftUpperX - borderWidth;
+  int     y = leftUpperY - borderWidth;
+  int     w = xkoord(verticalSize - 1) + borderWidth - x;
+  int     h = ykoord(coreSize) + borderWidth - y;
