+/* ******************************************************************* */
+
+#define A_expr buf
+#define B_expr buf2
+#define vallen 8
+static uChar opcode, modifier;
+static uChar statefine;
+static stateCol laststate;
+
+static uShrt line, linemax;
+static uChar vcont;
+static uShrt dspnt;
+static line_st *aline;
+
+/* ******************************************************************* */
+
+/* Here is the automaton */
+static void
+automaton(expr, state, cell)
+  char   *expr;
+  stateCol state;
+  mem_struct *cell;
+{
+  uChar   idx = 0;
+  char   *tmp;
+  ref_st *atbl;
+
+  switch (laststate = state) {
+
+  case S_OP:
+    statefine = FALSE;
+    if (get_token(expr, &idx, token) == CHARTOKEN) {
+      to_upper(token);
+      if ((opcode = str_in_set(token, opname)) < OPNUM)
+        automaton((char *) expr + idx, S_MOD_ADDR_EXP, cell);
+      else if (opcode < EQUOP)
+        automaton((char *) expr + idx, S_EXPR, cell);
+      else
+/* This should be toggled as error. No label should appear at this point */
+        LOGICERROR;
+    } else
+      errprn(EXPERR, aline, opcodeMsg);
+    break;
+
+  case S_MOD_ADDR_EXP:
+    statefine = FALSE;
+    switch (get_token(expr, &idx, token)) {
+    case MODFTOKEN:
+      automaton((char *) expr + idx, S_MODF, cell);
+      break;
+    case ADDRTOKEN:
+      cell->A_mode = (FIELD_T) ch_in_set(*token, addr_sym);
+#ifdef NEW_MODES
+      if (cell->A_mode > 4) {
+        if (SWITCH_8)
+          errprn(M88ERR, aline, "[*{}]");
+        else
+          cell->A_mode = SYM_TO_INDIR_A(cell->A_mode);
+      }
+#endif
+      automaton((char *) expr + idx, S_EXP_FS, cell);
+      break;
+    case NUMBTOKEN:
+    case EXPRTOKEN:
+      automaton(expr, S_EXP_FS, cell);
+      break;
+    case CHARTOKEN:
+      if ((atbl = lookup(token)) != NULL)
+        if (atbl->visit)
+          errprn(RECERR, aline, token);
+        else if (atbl->reftype == RTEXT)
+          if (atbl->sline) {
+            atbl->visit = TRUE;
+            automaton(atbl->sline->vline, S_MOD_ADDR_EXP, cell);
+            atbl->visit = FALSE;
+            automaton((char *) expr + idx, laststate, cell);
+          } else
+/* all slines should've been filled */
+            LOGICERROR;
+        else if ((tmp = (char *) MALLOC(sizeof(char) * vallen)) != NULL) {
+          sprintf(tmp, "%d", (int) atbl->value - line);
+          atbl->visit = TRUE;
+          automaton(tmp, S_MOD_ADDR_EXP, cell);
+          FREE(tmp);
+          atbl->visit = FALSE;
+          automaton((char *) expr + idx, laststate, cell);
+        } else
+          MEMORYERROR;
+      else if (!token[1])
+        automaton(expr, S_EXP_FS, cell);
+      else
+        errprn(SNFERR, aline, token);
+      break;
+    case NONE:
+      break;
+    default:
+      errprn(APPERR, aline, token);
+    }
+    break;
+
+  case S_MODF:
+    statefine = FALSE;
+    switch (get_token(expr, &idx, token)) {
+    case CHARTOKEN:
+      to_upper(token);
+      if ((modifier = str_in_set(token, modname)) < MODNUM)
+        automaton((char *) expr + idx, S_ADDR_EXP_A, cell);
+      else
+        errprn(EXPERR, aline, modifierMsg);
+      break;
+    case NONE:
+      break;
+    default:
+      errprn(EXPERR, aline, modifierMsg);
+    }
+    break;
+
+  case S_ADDR_EXP_A:
+    statefine = FALSE;
+    switch (get_token(expr, &idx, token)) {
+    case ADDRTOKEN:
+      cell->A_mode = (FIELD_T) ch_in_set(*token, addr_sym);
+#ifdef NEW_MODES
+      if (cell->A_mode > 4) {
+        if (SWITCH_8)
+          errprn(M88ERR, aline, "[*{}]");
+        else
+          cell->A_mode = SYM_TO_INDIR_A(cell->A_mode);
+      }
+#endif
+      automaton((char *) expr + idx, S_EXP_FS, cell);
+      break;
+    case NUMBTOKEN:
+    case EXPRTOKEN:
+      automaton(expr, S_EXP_FS, cell);
+      break;
+    case CHARTOKEN:
+      if ((atbl = lookup(token)) != NULL)
+        if (atbl->visit)
+          errprn(RECERR, aline, token);
+        else if (atbl->reftype == RTEXT)
+          if (atbl->sline) {
+            atbl->visit = TRUE;
+            automaton(atbl->sline->vline, S_ADDR_EXP_A, cell);
+            atbl->visit = FALSE;
+            automaton((char *) expr + idx, laststate, cell);
+          } else
+/* all slines should've been filled */
+            LOGICERROR;
+        else if ((tmp = (char *) MALLOC(sizeof(char) * vallen)) != NULL) {
+          sprintf(tmp, "%d", (int) atbl->value - line);
+          atbl->visit = TRUE;
+          automaton(tmp, S_ADDR_EXP_A, cell);
+          FREE(tmp);
+          atbl->visit = FALSE;
+          automaton((char *) expr + idx, laststate, cell);
+        } else
+          MEMORYERROR;
+      else if (!token[1])
+        automaton(expr, S_EXP_FS, cell);
+      else
+        errprn(SNFERR, aline, token);
+      break;
+    case NONE:
+      break;
+    default:
+      errprn(EXPERR, aline, aTerm);
+    }
+    break;
+
+  case S_EXP_FS:
+    switch (get_token(expr, &idx, token)) {
+    case FSEPTOKEN:
+      automaton((char *) expr + idx, S_ADDR_EXP_B, cell);
+      break;
+    case ADDRTOKEN:
+      if ((token[0] != '>') && (token[0] != '<') && (token[0] != '*'))
+        errprn(APPERR, aline, token);
+      else {
+        if (!concat(A_expr, token))
+          errprn(BUFERR, aline, "");
+        statefine = TRUE;
+        automaton((char *) expr + idx, S_EXP_FS, cell);
+      }
+      break;
+    case NUMBTOKEN:
+      if (!concat(token, " "))
+        errprn(BUFERR, aline, "");
+      /* FALLTHROUGH */
+    case EXPRTOKEN:
+      if (!concat(A_expr, token))
+        errprn(BUFERR, aline, "");
+      statefine = TRUE;
+      automaton((char *) expr + idx, S_EXP_FS, cell);
+      break;
+    case CHARTOKEN:
+      if ((atbl = lookup(token)) != NULL)
+        if (atbl->visit)
+          errprn(RECERR, aline, token);
+        else if (atbl->reftype == RTEXT)
+          if (atbl->sline) {
+            atbl->visit = TRUE;
+            automaton(atbl->sline->vline, S_EXP_FS, cell);
+            atbl->visit = FALSE;
+            automaton((char *) expr + idx, laststate, cell);
+          } else
+/* all slines should've been filled */
+            LOGICERROR;
+        else if ((tmp = (char *) MALLOC(sizeof(char) * vallen)) != NULL) {
+          sprintf(tmp, "%d", (int) atbl->value - line);
+          atbl->visit = TRUE;
+          automaton(tmp, S_EXP_FS, cell);
+          FREE(tmp);
+          atbl->visit = FALSE;
+          automaton((char *) expr + idx, laststate, cell);
+        } else
+          MEMORYERROR;
+      else if (!token[1])        /* check if it's a register. */
+        if (concat(A_expr, token)) {
+          statefine = TRUE;
+          automaton((char *) expr + idx, S_EXP_FS, cell);
+        } else
+          errprn(BUFERR, aline, "");
+      else
+        errprn(SNFERR, aline, token);
+      break;
+    case NONE:
+      break;
+    default:
+      errprn(APPERR, aline, token);
+    }
+    break;
+
+  case S_ADDR_EXP_B:
+    statefine = FALSE;
+    switch (get_token(expr, &idx, token)) {
+    case ADDRTOKEN:
+      cell->B_mode = (FIELD_T) ch_in_set(*token, addr_sym);
+#ifdef NEW_MODES
+      if (cell->B_mode > 4) {
+        if (SWITCH_8)
+          errprn(M88ERR, aline, "[*{}]");
+        else
+          cell->B_mode = SYM_TO_INDIR_A(cell->B_mode);
+      }
+#endif
+      automaton((char *) expr + idx, S_EXPR, cell);
+      break;
+    case NUMBTOKEN:
+    case EXPRTOKEN:
+      automaton(expr, S_EXPR, cell);
+      break;
+    case CHARTOKEN:
+      if ((atbl = lookup(token)) != NULL)
+        if (atbl->visit)
+          errprn(RECERR, aline, token);
+        else if (atbl->reftype == RTEXT)
+          if (atbl->sline) {
+            atbl->visit = TRUE;
+            automaton(atbl->sline->vline, S_ADDR_EXP_B, cell);
+            atbl->visit = FALSE;
+            automaton((char *) expr + idx, laststate, cell);
+          } else
+/* all slines should've been filled */
+            LOGICERROR;
+        else if ((tmp = (char *) MALLOC(sizeof(char) * vallen)) != NULL) {
+          sprintf(tmp, "%d", (int) atbl->value - line);
+          atbl->visit = TRUE;
+          automaton(tmp, S_ADDR_EXP_B, cell);
+          FREE(tmp);
+          atbl->visit = FALSE;
+          automaton((char *) expr + idx, laststate, cell);
+        } else
+          MEMORYERROR;
+      else if (!token[1])
+        automaton(expr, S_EXPR, cell);
+      else
+        errprn(SNFERR, aline, token);
+      break;
+    case NONE:
+      break;
+    default:
+      errprn(EXPERR, aline, bTerm);
+    }
+    break;
+
+  case S_EXPR:
+    switch (get_token(expr, &idx, token)) {
+    case ADDRTOKEN:
+      if ((token[0] != '>') && (token[0] != '<') && (token[0] != '*'))
+        errprn(APPERR, aline, token);
+      else {
+        if (!concat(B_expr, token))
+          errprn(BUFERR, aline, "");
+        statefine = TRUE;
+        automaton((char *) expr + idx, S_EXPR, cell);
+      }
+      break;
+    case NUMBTOKEN:
+      if (!concat(token, " "))
+        errprn(BUFERR, aline, "");
+      /* FALLTHROUGH */
+    case EXPRTOKEN:
+      if (!concat(B_expr, token))
+        errprn(BUFERR, aline, "");
+      statefine = TRUE;
+      automaton((char *) expr + idx, S_EXPR, cell);
+      break;
+    case CHARTOKEN:
+      if ((atbl = lookup(token)) != NULL)
+        if (atbl->visit)
+          errprn(RECERR, aline, token);
+        else if (atbl->reftype == RTEXT)
+          if (atbl->sline) {
+            atbl->visit = TRUE;
+            automaton(atbl->sline->vline, S_EXPR, cell);
+            atbl->visit = FALSE;
+            automaton((char *) expr + idx, S_EXPR, cell);
+          } else
+/* all slines should've been filled */
+            LOGICERROR;
+        else if ((tmp = (char *) MALLOC(sizeof(char) * vallen)) != NULL) {
+          if (opcode < OPNUM)
+            sprintf(tmp, "%d", (int) atbl->value - line);
+          else
+            sprintf(tmp, "%d", (int) atbl->value);
+          atbl->visit = TRUE;
+          automaton(tmp, S_EXPR, cell);
+          FREE(tmp);
+          atbl->visit = FALSE;
+          automaton((char *) expr + idx, S_EXPR, cell);
+        } else
+          MEMORYERROR;
+      else if (!token[1])        /* check for register use */
+        if (concat(B_expr, token)) {
+          statefine = TRUE;
+          automaton((char *) expr + idx, S_EXPR, cell);
+        } else
+          errprn(BUFERR, aline, "");
+      else
+        errprn(SNFERR, aline, token);
+      break;
+    case NONE:
+      break;
+    default:
+      errprn(APPERR, aline, token);
+    }
+    break;
+  }
+}
