+    showLines = bgiTextLines - 1;
+  else
+    showLines = screenY - 2;;
+#else
+#if defined(DOSGRXGRAPHX)
+  showLines = bgiTextLines - 1;
+#else
+#if defined(LINUXGRAPHX)
+  showLines = svgaTextLines - 1;
+#else
+#if defined(XWINGRAPHX)
+  showLines = xWinTextLines - 1;
+#else
+#if defined(CURSESGRAPHX)
+  showLines = LINES - 1;
