+#endif                                /* DJGPP */
+#endif
+  } else if ((mfp = fopen(fnStr, "r")) == NULL) {
+    sprintf(outs, cannotOpenMacroFile, fnStr);
+    cdb_fputs(outs, FORCE);
+    return;
+  }
+  while (1) {
+    i = 0;                        /* buffer index */
+    conLine = FALSE;
