+int
+xwin_decode(inputs, clip)
+  char   *inputs;
+  clp_opt_t **clip;
+{
+  int     i;
+
+  if (inputs[0] != '-')
+    return 0;
+  for (i = 0; i < xMaxOptions; i++)
+    if (strcmp(&inputs[1], xOptions[i]) == 0)
+      break;
+  if (i == xMaxOptions)
+    return 0;
+
+  xOpt.word = 'x';
+  xOpt.dtype = clp_str;
+  xOpt.storage = (pointer_t) & xStorage[i];
+  xOpt.def = i;                        /* remember which option this was */
+  xOpt.description = optXOpt[i];
+  *clip = &xOpt;
+
+  return 1;
+}
+#endif
+
+/*******************************************************************/
+
+void
+print_usage(clopt)
