+#if defined(DOSTXTGRAPHX) || defined(DOSGRXGRAPHX)  || defined(LINUXGRAPHX) \
+    || defined(XWINGRAPHX)
+#if defined(XWINGRAPHX)
+#define V_MAX        2994
