+
+/*
+ * adjust the position variables for a new panel
+ */
+void 
+svga_update(newcurPanel)
+  int             newcurPanel;
+{
+  if (curPanel == newcurPanel)
+    return;
+  if (curPanel == 0 && newcurPanel != 0) {
+    posx1 = posx;
+    posy1 = posy;
+    grwindx0 = xDim / 2;
+    grwindx1 = xDim - horizspace;
+    svga_clear();
+    posx2 = posx;
+    posy2 = posy;
+    curPanel = 2;
+  }
+  switch (newcurPanel) {
+  case 0:			/* only one panel */
+    if (curPanel == 1) {
+      posx1 = posx;
+      posy1 = posy;
+    }
+    grwindx0 = xDim / 2;
+    grwindx1 = xDim - horizspace;
+    svga_clear();
+    grwindx0 = 1;
+    grwindx1 = xDim - horizspace;
+    posx = posx1;
+    posy = posy1;
+    break;
+  case 1:			/* first panel */
+    grwindx0 = 1;
+    grwindx1 = xDim / 2 - horizspace;
+    if (curPanel == 2) {
+      posx2 = posx;
+      posy2 = posy;
+      posx = posx1;
+      posy = posy1;
+    }
+    break;
+  case 2:			/* second panel */
+    grwindx0 = xDim / 2;
+    grwindx1 = xDim - 10;
+    switch (curPanel) {
+    case 1:
+      posx1 = posx;
+      posy1 = posy;
+      posx = posx2;
+      posy = posy2;
+      break;
+    case 0:
+      posx1 = posx;
+      posy1 = posy;
+      svga_clear();
+    }
+    break;
+  }
+  curPanel = newcurPanel;
+}
