+/*
+ * return the x coordinate of the given core address
+ */
+int 
+xkoord(addr)
+  int             addr;
+{
+  return (LEFT_UPPER_X + ((addr) % verticalSize) * (size + 1));
+}
+
+/*
+ * return the y coordinate of the given core address
+ */
+int 
+ykoord(addr)
+  int             addr;
+{
+  return (LEFT_UPPER_Y + ((addr) / verticalSize) * (size + 1));
+}
