+/*
+ * write the menu line
+ */
+void 
+svga_write_menu()
+{
+  int             y, i, j;
+  char            s[7];
+
+  y = ykoord(coreSize) + BORDER_WIDTH + 2;
+
+  setcolor(writeColor);
+  svga_outtextxy(10, y, "<");
+
+  s[0] = CLEAR;
+  s[1] = '\0';
+
+  setcolor(RED);
+  for (i = 0; i < SPEEDLEVELS - displaySpeed; i++)
+    svga_outtextxy(20 + i * 10, y, s);
+
+  setcolor(YELLOW);
+  for (j = 0; j < displaySpeed; j++)
+    svga_outtextxy(20 + i * 10 + j * 10, y, s);
+
+  setcolor(writeColor);
+  svga_outtextxy(20 + i * 10 + j * 10, y, "> ");
+
+  for (i = 0; i < 5; i++) {
+    sprintf(s, "%d ", i);
+    if (displayLevel == i)
+      setcolor(RED);
+    else
+      setcolor(writeColor);
+    svga_outtextxy(170 + i * 10, y, s);
+  }
