+  if (xDim > 320) {		/* this is too simple */
+    if (inCdb)
+      setcolor(clearColor);
+    else
+      setcolor(writeColor);
+    svga_outtextxy(310, y, "space Quit");
+  }
+  setcolor(writeColor);
