+/**********************************************************************/
+/*   keyboard and mouse handling routines										 */
+/**********************************************************************/
+
+/*
+ * redraw the mouse cursor (if show is false, hide it) at the new
+ * location (newx/newy)
+ */
+void 
+draw_mouse_cursor(show, newx, newy)
+  int             show, newx, newy;
+{
+  static int      state = 0;	/* currently showing ? */
+  static int      xpos, ypos;	/* current mouse position */
+  static char     data[100];	/* saved screen image */
+
+  if (state && !show) {
+    gl_putbox(xpos - 1, ypos - 1, 3, 3, data);
+    state = 0;
+    xpos = ypos = -1;		/* force a redraw the next time */
+    return;
+  }
+  if (state && (newx != xpos || newy != ypos))
+    gl_putbox(xpos - 1, ypos - 1, 3, 3, data);
+  state = show;
+  if (!state || (newx == xpos && newy == ypos))
+    return;
+  xpos = newx;
+  ypos = newy;
+  gl_getbox(xpos - 1, ypos - 1, 3, 3, data);
+  gl_fillbox(xpos - 1, ypos - 1, 3, 3, WHITE);
+}
+
+/*
+ * convert a sequence of ASCII characters contained in buf into
+ * a 'key' (eg. 'A' or F12	or PGUP) -- this is ugly code at its best
+ * -- and I mean it ;-)
+ */
+static int 
+conv_chr(buf, ndx, maxndx)
+  char           *buf;
+  int            *ndx;
+  int             maxndx;
+{
+  int             i = *ndx;
+  int             ondx = *ndx;
+
+  if (*ndx >= maxndx)
+    return 0;
+  *ndx += 1;
+  if (buf[i++] != ESC)
+    return buf[ondx];
+
+  if (i < maxndx) {
+    if (buf[i++] != '[') {	/* must be Alt-a to Alt-z */
+      if (buf[i - 1] >= 'a' && buf[i - 1] <= 'z') {
+	*ndx = i;
+	return ALT_A + buf[i - 1] - 'a';
+      } else
+	return buf[ondx];
+    }
+    if (i >= maxndx)
+      return buf[ondx];
+    if (buf[i++] == '[') {	/* must be F1 through F5 */
+      if (i >= maxndx)
+	return buf[ondx];
+      *ndx = i + 1;
+      switch (buf[i]) {
+      case 'A':
+	return F1;
+      case 'B':
+	return F2;
+      case 'C':
+	return F3;
+      case 'D':
+	return F4;
+      case 'E':
+	return F5;
+      default:
+	return 0;
+      }
+    } else if (buf[i - 1] >= '1' && buf[i - 1] <= '6') {	/* must be HOME etc */
+      if (i >= maxndx)
+	return buf[ondx];
+      if (buf[i] != '~') {	/* could as well be F6 to F12 */
+	if (i + 1 >= maxndx)
+	  return buf[ondx];
+	if (buf[i + 1] != '~')
+	  return buf[ondx];
+	if (buf[i - 1] == '1') {
+	  *ndx = i + 2;
+	  switch (buf[i]) {
+	  case '7':
+	    return F6;
+	  case '8':
+	    return F7;
+	  case '9':
+	    return F8;
+	  default:
+	    return 0;
+	  }
+	} else if (buf[i - 1] == '2') {
+	  *ndx = i + 2;
+	  switch (buf[i]) {
+	  case '0':
+	    return F9;
+	  case '1':
+	    return F10;
+	  case '3':
+	    return F11;
+	  case '4':
+	    return F12;
+	  default:
+	    return 0;
+	  }
+	} else
+	  return buf[ondx];
+      }
+      *ndx = i-- + 1;
+      switch (buf[i]) {
+      case '1':
+	return HOME;
+      case '2':
+	return INS;
+      case '3':
+	return DEL;
+      case '4':
+	return END;
+      case '5':
+	return PGUP;
+      case '6':
+	return PGDN;
+      default:
+	return 0;
+      }
+    } else {			/* must be CURSOR keys */
+      *ndx = i--;
+      switch (buf[i]) {
+      case 'A':
+	return UP;
+      case 'B':
+	return DOWN;
+      case 'C':
+	return RIGHT;
+      case 'D':
+	return LEFT;
+      default:
+	return 0;
+      }
+    }
+  }
+  return buf[ondx];
+}
+
+/*
+ * wait for a key and return its symbolic representation (eg. 'A', F12, ..)
+ */
+int 
+svga_getch()
+{
+  int             x, max = 0;
+  char            buffer[20];
+  int             ndx = 0;
+
+  if (ndx < max)
+    return conv_chr(buffer, &ndx, max);
+
+  for (;;) {
+    if ((x = read(console_fd, buffer, 20)) == -1) {
+      if (errno == EINTR)
+	continue;
+      perror(cantReadConsole);
+      Exit(1);
+    }
+    break;
+  }
+  max = x;
+  ndx = 0;
+  return conv_chr(buffer, &ndx, max);
+}
+
+/*
+ * check if a key has been pressed and return it if read_flag is set,
+ * otherwise leave it unread. Return 0 if no key has been pressed.
+ */
+static char 
+keypressed(read_flag)
+  int             read_flag;
+{
+  fd_set          set;
+  struct timeval  timeout;
+  int             x;
+  char            buf[10];
+
+  FD_ZERO(&set);
+  FD_SET(console_fd, &set);
+  timeout.tv_sec = 0;
+  timeout.tv_usec = 0;
+
+  for (;;) {
+    if ((x = select(FD_SETSIZE, &set, NULL, NULL, &timeout)) == -1) {
+      if (errno == EINTR)
+	continue;
+      perror(selectFails);
+      Exit(1);
+    }
+    break;
+  }
+
+  if (x == 0)
+    return 0;
+  if (!read_flag)
+    return -1;
+  if (read(console_fd, buf, 1) == -1) {
+    perror(cantReadConsole);
+    Exit(1);
+  }
+  return buf[0];
+}
+
+/*
+ * check for mouse and key events, return 1 and set result if a mouse
+ * button gets pressed, return 0 if a keyboard event occurs
+ */
+static int 
+mouse_or_key(result)
+  char           *result;
+{
+  int             x, y, mx, my, button;
+  int             newLoc;
+  static int      lastbutton;
+
+  if (!mouseOK)
+    return 0;
+
+  mouse_setposition(xkoord(curAddr) + 1, ykoord(curAddr) + 1);
+  draw_mouse_cursor(1, xkoord(curAddr) + 1, ykoord(curAddr) + 1);
+
+  while (!keypressed(0)) {
+    mouse_update();
+    button = mouse_getbutton();
+    mx = mouse_getx();
+    my = mouse_gety();
+    draw_mouse_cursor(1, mx, my);
+
+    if (button != lastbutton) {
+      lastbutton = button;
+      if (button == 0)
+	continue;
+      x = mx - LEFT_UPPER_X + (size) / 2;
+      y = my - LEFT_UPPER_Y + (size) / 2;
+      newLoc = x / (size + 1) + (y / (size + 1)) * verticalSize;
+      if ((newLoc >= 0) && (newLoc < coreSize)) {
+	curAddr = newLoc;
+	if (button & MOUSE_LEFTBUTTON)
+	  strcpy(result, " m mousel\n");
+	else if (button & MOUSE_MIDDLEBUTTON)
+	  strcpy(result, " m mousem\n");
+	else if (button & MOUSE_RIGHTBUTTON)
+	  strcpy(result, " m mouser\n");
+	draw_mouse_cursor(0, 0, 0);
+	return 1;
+      }
+    }
+  }
+  draw_mouse_cursor(0, 0, 0);
+  return 0;
+}
+
+/*
+ * handle 'special' keys (ie. function/control/alt keys)
+ */
+static char    *
+special_keys(key, buf)
+  int             key;
+  char           *buf;
+{
+  if (key < 32) {
+    sprintf(buf, " m ctrl-%c\n", key + 96);
+    return buf;
+  }
+  if (key >= ALT_A && key <= ALT_Z) {
+    sprintf(buf, " m alt-%c\n", key + 'a' - ALT_A);
+    return buf;
+  }
+  switch (key) {
+  case INS:
+    strcpy(buf, " m ins\n");
+    break;
+  case DEL:
+    strcpy(buf, " m del\n");
+    break;
+  case UP:
+    strcpy(buf, " m up\n");
+    break;
+  case DOWN:
+    strcpy(buf, " m down\n");
+    break;
+  case LEFT:
+    strcpy(buf, " m left\n");
+    break;
+  case RIGHT:
+    strcpy(buf, " m right\n");
+    break;
+  case PGUP:
+    strcpy(buf, " m pgup\n");
+    break;
+  case PGDN:
+    strcpy(buf, " m pgdn\n");
+    break;
+  case HOME:
+    strcpy(buf, " m home\n");
+    break;
+  case END:
+    strcpy(buf, " m end\n");
+    break;
+  case F1:
+    strcpy(buf, " m f1\n");
+    break;
+  case F2:
+    strcpy(buf, " m f2\n");
+    break;
+  case F3:
+    strcpy(buf, " m f3\n");
+    break;
+  case F4:
+    strcpy(buf, " m f4\n");
+    break;
+  case F5:
+    strcpy(buf, " m f5\n");
+    break;
+  case F6:
+    strcpy(buf, " m f6\n");
+    break;
+  case F7:
+    strcpy(buf, " m f7\n");
+    break;
+  case F8:
+    strcpy(buf, " m f8\n");
+    break;
+  case F9:
+    strcpy(buf, " m f9\n");
+    break;
+  case F10:
+    strcpy(buf, " m f10\n");
+    break;
+  case F11:
+    strcpy(buf, " m f11\n");
+    break;
+  case F12:
+    strcpy(buf, " m f12\n");
+    break;
+  default:
+    buf[0] = '\n';
+    buf[1] = '\0';
+    break;
+  }
+  return buf;
+}
+
+/*
+ * read a line from the keyboard
+ */
+char           *
+svga_gets(result, maxchar)
+  char           *result;
+  int             maxchar;
+{
+  if (inputRedirection) {
+    return fgets(result, maxchar, stdin);
+  } else {
+    int             lo;
+    result[0] = 0;
+    point = 0;
+    cursoron();
+
+    do {
+      if (mouse_or_key(result))
+	return result;
+      lo = svga_getch();
+      if (lo) {
+	switch (lo) {
+	case BS:
+	  delchar();
+	  break;
+	case ESC:
+	  while (point)
+	    delchar();
+	  break;
+	case CR:
+	  cursoroff();
+	  newline();
+	  break;
+	default:
+	  if (lo >= 32 && lo < 128) {
+	    result[point++] = lo;
+	    if (point > maxchar - 1)
+	      lo = CR;
+	    cursoroff();
+	    str[0] = lo;
+	    svga_outtextxy(posx, posy, str);
+	    newchar();
+	    cursoron();
+	  } else {
+	    special_keys(lo, result);
+	    cursoroff();
+	    svga_puts(result);
+	    return result;
+	  }
+	}
+      }
+    } while (lo != CR);
+    result[point++] = '\n';
+    result[point] = 0;
+    if (point)
+      return result;
+    else
+      return NULL;
+  }				/* !inputRedirection */
+}
