+/**********************************************************************/
+/*   keyboard and mouse handling routines                                                                                 */
+/**********************************************************************/
+
+/*
+ * convert a KeyPress event to an integer representing the key
+ */
+static unsigned long
+conv_key(event)
+  XEvent *event;
+{
+  KeySym  keysym;
+  static unsigned char buffer[20];
+  XComposeStatus compose;
+  int     count;
+
+  count = XLookupString(&event->xkey, buffer, 20, &keysym, &compose);
+
+  controlPressed = (event->xkey.state & ControlMask);
+  altPressed = (event->xkey.state & Mod1Mask);
+
+  if (count == 1 && buffer[0] >= 32 && buffer[0] <= 127)
+    return buffer[0];
+  else
+    return (unsigned long) keysym;
+}
+
+/*
+ * wait for a keypress, return the key
+ */
+static unsigned long
+xWin_getch()
+{
+  XEvent  event;
+
+  for (;;) {
+    XNextEvent(display, &event);
+    if (event.type == KeyPress)
+      return conv_key(&event);
+    handle_event(&event);
+  }
+}
+
+/*
+ * check for mouse and key events, return 1 and set result if a mouse
+ * button gets pressed, return 0 and the key if a keyboard event
+ * occurs
+ */
+static int
+mouse_or_key(result, key)
+  char   *result;
+  unsigned long *key;
+{
+  XEvent  event;
+  int     x, y;
+  int     mouseLoc;
+
+  XWarpPointer(display, xwindow, xwindow, 0, 0, xDim + 1, yDim + 1,
+               xkoord(curAddr) + 1, ykoord(curAddr) + 1);
+
+  for (;;) {
+    XNextEvent(display, &event);
+
+    switch (event.type) {
+    case KeyPress:
+      *key = conv_key(&event);
+      return 0;
+
+    case ButtonPress:
+      switch (event.xbutton.button) {
+      case Button1:
+        strcpy(result, " m mousel\n");
+        break;
+      case Button2:
+        strcpy(result, " m mouser\n");
+        break;
+      case Button3:
+        strcpy(result, " m mousem\n");
+        break;
+      default:
+        continue;
+      }
+      x = event.xbutton.x - leftUpperX + size / 2;
+      y = event.xbutton.y - leftUpperY + size / 2;
+
+      mouseLoc = x / (size + 1) + (y / (size + 1)) * verticalSize;
+      if ((mouseLoc >= 0) && (mouseLoc < coreSize)) {
+        curAddr = mouseLoc;
+        return 1;
+      }
+      break;
+
+    default:
+      handle_event(&event);
+    }
+  }
+
+  return 0;
+}
+
+/*
+ * handle 'special' keys (ie. function/control/alt keys)
+ */
+static char *
+special_keys(key, buf)
+  unsigned long key;
+  char   *buf;
+{
+  if (controlPressed && key < 128) {
+    sprintf(buf, " m ctrl-%c\n", (char) key);
+    return buf;
+  }
+  if (altPressed && key < 128) {
+    sprintf(buf, " m alt-%c\n", (char) key);
+    return buf;
+  }
+  switch (key) {
+  case XK_Tab:
+    strcpy(buf, " m ctrl-i\n");
+    break;
+  case XK_Insert:
+    strcpy(buf, " m ins\n");
+    break;
+  case XK_Delete:
+    strcpy(buf, " m del\n");
+    break;
+  case XK_Up:
+    strcpy(buf, " m up\n");
+    break;
+  case XK_Down:
+    strcpy(buf, " m down\n");
+    break;
+  case XK_Left:
+    strcpy(buf, " m left\n");
+    break;
+  case XK_Right:
+    strcpy(buf, " m right\n");
+    break;
+#ifdef XK_Page_Up
+  case XK_Page_Up:
+    strcpy(buf, " m pgup\n");
+    break;
+#else
+#ifdef XK_Prior
+  case XK_Prior:
+    strcpy(buf, " m pgup\n");
+    break;
+#endif
+#endif
+#ifdef XK_Page_Down
+  case XK_Page_Down:
+    strcpy(buf, " m pgdn\n");
+    break;
+#else
+#ifdef XK_Next
+  case XK_Next:
+    strcpy(buf, " m pgdn\n");
+    break;
+#endif
+#endif
+  case XK_Begin:
+    strcpy(buf, " m home\n");
+    break;
+  case XK_End:
+    strcpy(buf, " m end\n");
+    break;
+  case XK_F1:
+    strcpy(buf, " m f1\n");
+    break;
+  case XK_F2:
+    strcpy(buf, " m f2\n");
+    break;
+  case XK_F3:
+    strcpy(buf, " m f3\n");
+    break;
+  case XK_F4:
+    strcpy(buf, " m f4\n");
+    break;
+  case XK_F5:
+    strcpy(buf, " m f5\n");
+    break;
+  case XK_F6:
+    strcpy(buf, " m f6\n");
+    break;
+  case XK_F7:
+    strcpy(buf, " m f7\n");
+    break;
+  case XK_F8:
+    strcpy(buf, " m f8\n");
+    break;
+  case XK_F9:
+    strcpy(buf, " m f9\n");
+    break;
+  case XK_F10:
+    strcpy(buf, " m f10\n");
+    break;
+  case XK_F11:
+    strcpy(buf, " m f11\n");
+    break;
+  case XK_F12:
+    strcpy(buf, " m f12\n");
+    break;
+  default:
+    return NULL;
+  }
+  return buf;
+}
+
+/*
+ * read a line from the keyboard
+ */
+char   *
+xWin_gets(result, maxchar)
+  char   *result;
+  int     maxchar;
+{
+  if (inputRedirection) {
+    return fgets(result, maxchar, stdin);
+  } else {
+    unsigned long lo;
+    result[0] = 0;
+    point = 0;
+    cursoron();
+
+    do {
+      if (mouse_or_key(result, &lo))
+        return result;
+      if (lo) {
+        if (special_keys(lo, result) != NULL) {
+          cursoroff();
+          xWin_puts(result);
+          return result;
+        }
+        switch (lo) {
+        case XK_BackSpace:
+        case XK_Delete:
+          delchar();
+          break;
+        case XK_Escape:
+          while (point)
+            delchar();
+          break;
+        case XK_Return:
+        case XK_KP_Enter:
+        case XK_Linefeed:
+          cursoroff();
+          newline();
+          break;
+        default:
+          if (lo >= 32 && lo < 128) {
+            result[point++] = lo;
+            if (point > maxchar - 1)
+              lo = XK_Return;
+            cursoroff();
+            str[0] = lo;
+            xWin_outtextxy(posx, posy, str);
+            newchar();
+            cursoron();
+          }
+        }
+      }
+    } while (lo != XK_Return && lo != XK_KP_Enter && lo != XK_Linefeed);
+    result[point++] = '\n';
+    result[point] = 0;
+    if (point)
+      return result;
+    else
+      return NULL;
+  }                                /* !inputRedirection */
+}
