+/*
+ * resize the window
+ */
+void
+xWin_resize(void)
+{
+  int     xsize, ysize;
+
+  switch (displayMode) {
+  case 1:
+    xsize = 640;
+    ysize = 480;
+    break;
+  case 2:
+    xsize = 800;
+    ysize = 600;
+    break;
+  case 3:
+    xsize = 1024;
+    ysize = 768;
+    break;
+  case 4:
+    xsize = 640;
+    ysize = 200;
+    break;
+  case 5:
+    xsize = 640;
+    ysize = 350;
+    break;
