+      textout(outs);
+      break;
+    case RLABEL:
+      textout(labelMsg);
+      sprintf(outs, "%5d\n\n", aref->value);
+      textout(outs);
+      break;
+    }
+  }
+
+  textout(endOfChart);
+}
