+/* Handle all keys except interrupting keys */
+  cbreak();
+
+/* Do not echo the typed keys */
+  noecho();
+
+/* Do not use curses NL -> CR/LF or CR -> NL translation. Use linefeed cap
+   if possible */
+  nonl();
