+int
+newpg()
+{
+  int     pg = 0;
+  win_t  *awin;
+
+  do {
+    switch (pg) {
+    case CDB_PAGE:
+    case CORE_PAGE:
+    case DEF_PAGE:
+    case HELP_PAGE:
+      break;
+    default:
+      for (awin = globalwin; awin && awin->page != pg;
+           awin = awin->nextwin);
+      if (!awin)
+        return pg;
+    }
+    pg++;
+  } while (pg != -1);
+
+  escape("Sorry, but I think the program is about to crash!", "newpg()",
+         GRAPHERR);
