+  if (win)
+    if (page == CDB_PAGE && curPanel) {
+      touchwin(cdbwin);
+      wrefresh(cdbwin);
+      touchwin(cdbwin2);
+      wrefresh(cdbwin2);
+      curwin = curPanel == 1 ? cdbwin : cdbwin2;
+      return;
+    } else
+      curwin = win->win;
+  else
+    curwin = createwindow(LINES, COLS, 0, 0, page)->win;
