+      while (!kbhit());
+    else
+      getch();
+  }
+  textmode(LASTMODE);
+  displayMode = TEXT;                /* to display results in textmode */
+#ifdef DOSTXTGRAPHX
+  ScreenUpdate(Screen[DEF_PAGE]);        /* restore text screen */
