+#define CACHE 2
+void
+CacheScreenUpdate(short *buf)
+{
+  register int idx = 0;
+  while (idx < screenSize - 1) {/* -1; otherwise window scrolls */
+    if (Screen[CACHE][idx] != buf[idx]) {
+      gotoxy((idx % screenX) + 1, (idx / screenX) + 1);
+      textattr(buf[idx] >> 8);
+      putch(buf[idx] & 0x00FF);
+      Screen[CACHE][idx] = buf[idx];
+    }
+    ++idx;
+  }
+}
