+  regs.x.eax = 0x0100;
+  regs.x.ecx = (start * 256) + end;
+  int386(0x10, &regs, &regs);
+#else
+  union REGS regs;
+  regs.x.ax = 0x0100;
+  regs.x.cx = (start * 256) + end;
