+	if (IR.B_value == 1)
+	  break;
+	push(addrA);
+	goto nopush;
+
+      case OP(DJN, mF):
+      case OP(DJN, mI):
+      case OP(DJN, mX):
+	if (ISNEG(--memory[addrB].B_value))
+	  memory[addrB].B_value = coreSize1;
+	if (ISNEG(--memory[addrB].A_value))
+	  memory[addrB].A_value = coreSize1;
+	display_dec(addrB);
+#ifdef RWLIMIT
+	display_read(raddrB);
+#endif
+#ifdef NEW_MODES
+	if ((AB_Value == 1) && (IR.B_value == 1))
+	  break;
+#else
+	if ((!memory[addrB].A_value) && (IR.B_value == 1))
+	  break;
+#endif
+	push(addrA);
+	goto nopush;
+
+#ifdef NEW_OPCODES
+      case OP(SEQ, mA):
+#endif
+      case OP(CMP, mA):
+	display_read(raddrB);
+	display_read(addrA);
+	if (ADDRB_AVALUE != ADDRA_AVALUE)
+	  break;
+	ADDMOD(progCnt, 2, temp);
+	goto pushtemp;
+
+#ifdef NEW_OPCODES
+      case OP(SEQ, mI):
+#endif
+      case OP(CMP, mI):
+	display_read(raddrB);
+	display_read(addrA);
+	if ((memory[raddrB].opcode != memory[addrA].opcode) ||
+	    (memory[raddrB].A_mode != memory[addrA].A_mode) ||
+	    (memory[raddrB].B_mode != memory[addrA].B_mode))
+	  break;
+	/* FALLTHRU */
+#ifdef NEW_OPCODES
+      case OP(SEQ, mF):
+#endif
+      case OP(CMP, mF):
+	display_read(raddrB);
+	display_read(addrA);
+	if (ADDRB_AVALUE != ADDRA_AVALUE)
+	  break;
+	/* FALLTHRU */
+#ifdef NEW_OPCODES
+      case OP(SEQ, mB):
+#endif
+      case OP(CMP, mB):
+	display_read(raddrB);
+	display_read(addrA);
+	if (IR.B_value != IR.A_value)
+	  break;
+	ADDMOD(progCnt, 2, temp);
+	goto pushtemp;
+
+#ifdef NEW_OPCODES
+      case OP(SEQ, mAB):
+#endif
+      case OP(CMP, mAB):
+	display_read(raddrB);
+	display_read(addrA);
+	if (IR.B_value != ADDRA_AVALUE)
+	  break;
+	ADDMOD(progCnt, 2, temp);
+	goto pushtemp;
+
+#ifdef NEW_OPCODES
+      case OP(SEQ, mX):
+#endif
+      case OP(CMP, mX):
+	display_read(raddrB);
+	display_read(addrA);
+	if (IR.B_value != ADDRA_AVALUE)
+	  break;
+	/* FALLTHRU */
+#ifdef NEW_OPCODES
+      case OP(SEQ, mBA):
+#endif
+      case OP(CMP, mBA):
+	display_read(raddrB);
+	display_read(addrA);
+	if (ADDRB_AVALUE != IR.A_value)
+	  break;
+	ADDMOD(progCnt, 2, temp);
+	goto pushtemp;
+
+#ifdef NEW_OPCODES
+      case OP(SNE, mA):
+	display_read(raddrB);
+	display_read(addrA);
+	if (ADDRB_AVALUE != ADDRA_AVALUE)
+	  goto skip;
+	break;
+    skip:
+	ADDMOD(progCnt, 2, temp);
+	goto pushtemp;
+
+      case OP(SNE, mI):
+	display_read(raddrB);
+	display_read(addrA);
+	if ((memory[raddrB].opcode != memory[addrA].opcode) ||
+	    (memory[raddrB].A_mode != memory[addrA].A_mode) ||
+	    (memory[raddrB].B_mode != memory[addrA].B_mode))
+	  goto skip;
+	/* FALLTHRU */
+      case OP(SNE, mF):
+	display_read(raddrB);
+	display_read(addrA);
+	if (ADDRB_AVALUE != ADDRA_AVALUE)
+	  goto skip;
+	/* FALLTHRU */
+      case OP(SNE, mB):
+	display_read(raddrB);
+	display_read(addrA);
+	if (IR.B_value != IR.A_value)
+	  goto skip;
+	break;
+
+      case OP(SNE, mAB):
+	display_read(raddrB);
+	display_read(addrA);
+	if (IR.B_value != ADDRA_AVALUE)
+	  goto skip;
+	break;
+
+      case OP(SNE, mX):
+	display_read(raddrB);
+	display_read(addrA);
+	if (IR.B_value != ADDRA_AVALUE)
+	  goto skip;
+	/* FALLTHRU */
+      case OP(SNE, mBA):
+	display_read(raddrB);
+	display_read(addrA);
+	if (ADDRB_AVALUE != IR.A_value)
+	  goto skip;
+	break;
+#endif
+
+      case OP(SLT, mA):
+	display_read(raddrB);
+	display_read(addrA);
+	if (ADDRB_AVALUE <= ADDRA_AVALUE)
+	  break;
+	ADDMOD(progCnt, 2, temp);
+	goto pushtemp;
+
+      case OP(SLT, mF):
+      case OP(SLT, mI):
+	display_read(raddrB);
+	display_read(addrA);
+	if (ADDRB_AVALUE <= ADDRA_AVALUE)
+	  break;
+	/* FALLTHRU */
+      case OP(SLT, mB):
+	display_read(raddrB);
+	display_read(addrA);
+	if (IR.B_value <= IR.A_value)
+	  break;
+	ADDMOD(progCnt, 2, temp);
+	goto pushtemp;
+
+      case OP(SLT, mAB):
+	display_read(raddrB);
+	display_read(addrA);
+	if (IR.B_value <= ADDRA_AVALUE)
+	  break;
+	ADDMOD(progCnt, 2, temp);
+	goto pushtemp;
+
+      case OP(SLT, mX):
+	display_read(raddrB);
+	display_read(addrA);
+	if (IR.B_value <= ADDRA_AVALUE)
+	  break;
+	/* FALLTHRU */
+      case OP(SLT, mBA):
+	display_read(raddrB);
+	display_read(addrA);
+	if (ADDRB_AVALUE <= IR.A_value)
+	  break;
+	ADDMOD(progCnt, 2, temp);
+	goto pushtemp;
+
+
+      case OP(JMP, mA):
+      case OP(JMP, mB):
+      case OP(JMP, mAB):
+      case OP(JMP, mBA):
+      case OP(JMP, mF):
+      case OP(JMP, mX):
+      case OP(JMP, mI):
+	push(addrA);
+	goto nopush;
+
+
+      case OP(SPL, mA):
+      case OP(SPL, mB):
+      case OP(SPL, mAB):
+      case OP(SPL, mBA):
+      case OP(SPL, mF):
+      case OP(SPL, mX):
+      case OP(SPL, mI):
+//        temp = progCnt + 1;
+	if ((temp = progCnt + 1) == coreSize)
+	  temp = 0;
+	push(temp);
+
+	if (W->tasks >= taskNum)
+	  goto nopush;
+	++W->tasks;
+	display_spl(W - warrior, W->tasks);
+	push(addrA);
+	goto nopush;
+
+
+      case OP(DAT, mA):
+      case OP(DAT, mB):
+      case OP(DAT, mAB):
+      case OP(DAT, mBA):
+      case OP(DAT, mF):
+      case OP(DAT, mX):
+      case OP(DAT, mI):
+    die:
+	display_dat(progCnt, W - warrior, W->tasks);
+	if (--W->tasks)
+	  goto nopush;
+	display_die(W - warrior);
+	W->score[warriorsLeft + warriors - 2]++;
+	cycle = cycle - 1 - (cycle - 1) / (warriorsLeft--);
+	if (warriorsLeft < 2)
+	  goto nextround;        /* can't use break because in switch */
+
+#ifndef SERVER
+	if (debugState == BREAK) {
+	  sprintf(outs, warriorTerminated, W - warrior, W->name);
+	  debugState = cdb(outs);
+	}
+#endif                                /* SERVER */
+	oldW->nextWarrior = W = W->nextWarrior;
+	continue;
+
+	/* $EXT$ insert code for new opcodes here */
+
+#ifdef NEW_OPCODES
+      case OP(NOP, mA):
+      case OP(NOP, mB):
+      case OP(NOP, mAB):
+      case OP(NOP, mBA):
+      case OP(NOP, mF):
+      case OP(NOP, mX):
+      case OP(NOP, mI):
+	break;
+#endif
+
+#ifdef PSPACE
+      case OP(LDP, mA):
+	display_read(addrA);
+	memory[addrB].A_value = get_pspace(ADDRA_AVALUE);
+	display_write(addrB);
+	break;
+
+      case OP(LDP, mF):
+      case OP(LDP, mX):
+      case OP(LDP, mI):
+      case OP(LDP, mB):
+	display_read(addrA);
+	memory[addrB].B_value = get_pspace(IR.A_value);
+	display_write(addrB);
+	break;
+
+      case OP(LDP, mAB):
+	display_read(addrA);
+	memory[addrB].B_value = get_pspace(ADDRA_AVALUE);
+	display_write(addrB);
+	break;
+
+      case OP(LDP, mBA):
+	display_read(addrA);
+	memory[addrB].A_value = get_pspace(IR.A_value);
+	display_write(addrB);
+	break;
+
+      case OP(STP, mA):
+	display_read(addrA);
+	set_pspace(ADDRB_AVALUE, ADDRA_AVALUE);
+	break;
+
+      case OP(STP, mF):
+      case OP(STP, mX):
+      case OP(STP, mI):
+      case OP(STP, mB):
+	display_read(addrA);
+	set_pspace(IR.B_value, IR.A_value);
+	break;
+
+      case OP(STP, mAB):
+	display_read(addrA);
+	set_pspace(IR.B_value, ADDRA_AVALUE);
+	break;
+
+      case OP(STP, mBA):
+	display_read(addrA);
+	set_pspace(ADDRB_AVALUE, IR.A_value);
+	break;
+#endif                                /* PSPACE */
+      case OP(MOV, mI):
+	display_read(addrA);
+#ifndef SERVER
+	if (!copyDebugInfo)
+	  temp = memory[addrB].debuginfo;
+#endif
+	memory[addrB] = memory[addrA];
+#ifndef SERVER
+	if (!copyDebugInfo)
+	  memory[addrB].debuginfo = temp;
+#endif
+	memory[addrB].B_value = IR.A_value;
+#ifdef NEW_MODES
+	memory[addrB].A_value = AA_Value;
+#endif
+	display_write(addrB);
+//        break;
+#if 0
+      default:
+	errout(fatalErrorInSimulator);
+#ifdef PERMUTATE
+        if(permbuf) {
+          free(permbuf);
+          permbuf = NULL;
+        }
+#endif
+#ifndef DOS16
+	/* DOS taskQueue may not be free'd because of segment wrap-around */
+	free(memory);
+	free(taskQueue);
+	alloc_p = 0;
+#endif
+	Exit(SERIOUS);
+#endif
+      }                                /* end switch */
+
+      /* push the next instruction onto queue */
+ //     temp = progCnt + 1;
+      if ((temp=progCnt + 1) == coreSize)
+	temp = 0;
+  pushtemp:                        /* push whatever's in temp onto queue */
+      push(temp);
+
+  nopush:                        /* just go to the next warrior/cycle */
+      oldW = W;
+      W = W->nextWarrior;
+//      --cycle;
+    } while (--cycle);                /* next cycle */
+nextround:
+    for (temp = 0; temp < warriors; temp++) {
+      if (warrior[temp].tasks) {
+	warrior[temp].score[warriorsLeft - 1]++;
+#ifdef PSPACE
+	warrior[temp].lastResult = warriorsLeft;
+      } else
+	warrior[temp].lastResult = 0;
+#else
+      }
+#endif
+    }
+    if (starter == endWar - 1)
+      starter = warrior;
+    else
+      ++starter;
+#ifndef SERVER
+    if (debugState == BREAK) {
+      if (warriorsLeft == 1 && warriors != 1)
+	sprintf(outs, warriorTerminatedEndOfRound, W - warrior, W->name, round);
+      else
+	sprintf(outs, endOfRound, round);
+      debugState = cdb(outs);
+    }
+#endif
+  } while (++round <= rounds);
+
+  display_close();
+#ifdef PERMUTATE
+  if(permbuf) {
+    free(permbuf);
+    permbuf = NULL;
+  }
+#endif
+#ifndef DOS16
+  /* DOS taskQueue may not be free'd because of segment wrap-around */
+  free(memory);
+  free(taskQueue);
+  alloc_p = 0;
+#endif
+}

