+          keyDelay = keyDelayAr[displaySpeed];
+        }
+        break;
+      case '<':
+        if (displaySpeed < SPEEDLEVELS - 1) {
+          ++displaySpeed;
+          loopDelay = loopDelayAr[displaySpeed];
+          keyDelay = keyDelayAr[displaySpeed];
+        }
