+
+#define ESC 27
+#define BS 8
+#define LF 10
+#define CR 13
+#define CLEAR 219
+#define MAXLENGTH 160
+#define HORIZSPACE 8
+
+int     posx, posy;                /* for current panel */
+int     posx1, posy1;                /* for panel 1 */
+int     posx2, posy2;                /* for panel 2 */
+int     scrollx1, scrollx2;
