+void    grputs(char *);
+
+void 
+grupdate(int newcurPanel)
+{
+  if (curPanel == newcurPanel)
+    return;
+  if (curPanel == 0 && newcurPanel != 0) {
+    posx1 = posx;
+    posy1 = posy;
+    grwindx0 = GrMaxX() / 2;
+    grwindx1 = GrMaxX() - HORIZSPACE;
+    grclear();
+    posx2 = posx;
+    posy2 = posy;
+    curPanel = 2;
+  }
+  switch (newcurPanel) {
+  case 0:                        /* only one panel */
+    if (curPanel == 1) {
+      posx1 = posx;
+      posy1 = posy;
+    }
+    grwindx0 = GrMaxX() / 2;
+    grwindx1 = GrMaxX() - HORIZSPACE;
+    grclear();
+    grwindx0 = 1;
+    grwindx1 = GrMaxX() - HORIZSPACE;
+    posx = posx1;
+    posy = posy1;
+    scrollx1 = 1;
+    scrollx2 = 79;
+    break;
+  case 1:                        /* first panel */
+    grwindx0 = 1;
+    grwindx1 = GrMaxX() / 2 - HORIZSPACE;
+    if (curPanel == 2) {
+      posx2 = posx;
+      posy2 = posy;
+      posx = posx1;
+      posy = posy1;
+    }
+    scrollx1 = 1;
+    scrollx2 = 39;
+    break;
+  case 2:                        /* second panel */
+    grwindx0 = GrMaxX() / 2;
+    grwindx1 = GrMaxX() - 10;
+    switch (curPanel) {
+    case 1:
+      posx1 = posx;
+      posy1 = posy;
+      posx = posx2;
+      posy = posy2;
+      break;
+    case 0:
+      posx1 = posx;
+      posy1 = posy;
+      grclear();
+    }
+    scrollx1 = 40;
+    scrollx2 = 79;
+    break;
+  }
+  curPanel = newcurPanel;
+}
+
+void 
+graphio_init(void)
+{
+  switch (graphdriver) {
+    default:scrollPixel = 16;
+    lastLine = 29;
+    verspace = 10;                /* 8 */
+    break;
+/*      case EGA : scrollPixel= 14;
+     lastLine = 24;
+     verspace = 8;
+         break;
+      case CGA : scrollPixel= 8;
+         lastLine = 24;
+         verspace = 8;
+*/
+  }
+  scrollLines = (GrMaxY() - grwindy0) / scrollPixel;
+  grwindy0 = 1 + GrMaxY() - scrollPixel * (scrollLines);
+  bgiTextLines = (GrMaxY() - grwindy0) / verspace;        /* used for pausing in
+                                                         * cdb */
+}
+
+
+void
+grclear()
+{
+  posx = grwindx0;
+  posy = grwindy0;
+/*  setfillstyle(EMPTY_FILL, WHITE); */
+  GrFilledBox(grwindx0, grwindy0, grwindx1 + HORIZSPACE - 1, GrMaxY(), GrBlack());
+}
+
+void
+newline(void)
+{
+  union REGS regs;
+  posx = grwindx0;
+  posy += verspace;
+  if (posy > grwindy1) {
+    posy -= verspace;
+    switch (graphdriver) {
+    default:
+      GrBitBlt(NULL, grwindx0, grwindy0, NULL, grwindx0, grwindy0 + verspace,
+               grwindx1 + HORIZSPACE - 1, GrMaxX(), GrWRITE);
+      GrFilledBox(grwindx0, posy, grwindx1 + HORIZSPACE - 1, GrMaxY(), GrBlack());
+/*    case VGA :
+    case EGA :
+    case CGA :
+
+  regs.x.ax=0x0600+ 1 ;
+  regs.x.bx= 0;
+  regs.x.cx=( (lastLine-scrollLines+1) <<8)+ scrollx1 ;
+  regs.x.dx=( lastLine <<8)+ scrollx2 ;
+  int86(0x10,&regs,&regs);
+  posy -= (scrollPixel-verspace) ;
+     break;
+      default:
+      grclear();
+*/
+    }
+  }
+}
+
+void
+newchar(void)
+{
+  posx += HORIZSPACE;
+  if (posx > grwindx1 - HORIZSPACE)
+    newline();
+}
+
+#define cursoron() outtextxy(posx, posy, "_")
+
+#define cursoroff() setcolor(BLACK); \
+str[0]=CLEAR;                        \
+outtextxy(posx, posy, str);          \
+setcolor(graphioColor)
+
+void
+delchar(void)
+{
+  if (point) {
+    cursoroff();
+    posx -= HORIZSPACE;
+    if (posx < grwindx0) {
+      posx = grwindx0;
+      cursoron();
+    } else {
+      --point;
+      cursoroff();
+      cursoron();
+    }
+  }
+}
+
+char   *
+grgets(char *result, int maxchar)
+{
+  if (inputRedirection) {
+    return fgets(result, maxchar, stdin);
+  } else {
+    int     lo;
+    result[0] = 0;
+    point = 0;
+    cursoron();
+
+    do {
+      if (mouse_or_key(result))
+        return result;
+      lo = getch();
+      if (lo) {
+        switch (lo) {
+        case BS:
+          delchar();
+          break;
+        case ESC:
+          while (point)
+            delchar();
+          break;
+        case CR:
+          cursoroff();
+          newline();
+          break;
+/*       case '\t':
+    cursoroff();
+    grputs("    ");
+    lo=' ';    I'd like tab to be a macro for switch, Nandor */
+        default:
+          if (lo >= 32 && lo < 128) {
+            result[point++] = lo;
+            if (point > maxchar - 1)
+              lo = CR;
+            cursoroff();
+            str[0] = lo;
+            outtextxy(posx, posy, str);
+            newchar();
+            cursoron();
+          } else if (lo > 127) {
+            ukey2macro(lo, result);
+            cursoroff();
+            grputs(result);
+            return result;
+          } else {
+            ckey2macro(lo, result);
+            cursoroff();
+            grputs(result);
+            return result;
+          }
+        }
+
+      } else {
+        xkey2macro(getch(), result);
+        cursoroff();
+        grputs(result);                /* Stefan you might want to change this,
+                                 * Nandor */
+        return result;
+      }
+    } while (lo != CR);
+    result[point++] = '\n';
+    result[point] = 0;
+    if (point)
+      return result;
+    else
+      return NULL;
+  }                                /* !inputRedirection */
+}
+
+void
+grputs(char *sss)
+{
+  if (printAttr) {
+    graphioColor = colors[printAttr - 1];
+    setcolor(graphioColor);
+  } else {
+    graphioColor = WHITE;
+    setcolor(graphioColor);
+  }
+  while (*sss) {
+    switch (*sss) {
+    case '\n':
+      newline();
+      break;
+    default:
+      str[0] = *sss;
+      outtextxy(posx, posy, str);
+      newchar();
+    }
+    ++sss;
+  }
+}
+
+
