+{
+  fprintf(stderr, "%s", s);
+  Exit(1);
+}
+
+/*
+ * convert the given string into a number
+ */
+static int
+make_int(s)
+  char   *s;
+{
+  char   *err;
+  int     r;
+
+  r = (int) strtol(s, &err, 10);
+  if (*err != '\0')
+    my_err(invalidGeom);
+  return r;
+}
+
+/*
+ * parse the string specifying the geometry and return it in the
+ * parameters, set sizeHint's flags member to indicate the parameters
+ * specified
+ */
+static void
+parse_geometry(sizeHints, x, y, w, h)
+  XSizeHints *sizeHints;
+  int    *x, *y, *w, *h;
+{
+  char   *g = geometry, *s, *t;
+  char    c;
+
+  sizeHints->flags = 0;
+
+  if (g[0] != '+' && g[0] != '-') {        /* first parse width & height */
+    sizeHints->flags |= USSize;
+
+    if ((s = strchr(g + 1, 'x')) == NULL)
+      my_err(invalidGeom);
+    *s = '\0';
+    *w = make_int(g);
+    if (*w < MIN_WIDTH)
+      *w = MIN_WIDTH;
+    g = s + 1;
+
+    if (strchr(g + 1, '+') == NULL && strchr(g + 1, '-') == NULL) {
+      *h = make_int(g);
+      if (*h < MIN_HEIGHT)
+        *h = MIN_HEIGHT;
+      return;
+    }
+    s = strchr(g + 1, '+');
+    t = strchr(g + 1, '-');
+    if (s == NULL)
+      s = t;
+    else if (t != NULL)
+      if (t < s)
+        s = t;
+    if (s == NULL)
+      my_err(invalidGeom);        /* this should never happen ! */
+
+    c = *s;
+    *s = '\0';
+    *h = make_int(g);
+    if (*h < MIN_HEIGHT)
+      *h = MIN_HEIGHT;
+
+    *s = c;
+    g = s;
+  }
+  sizeHints->flags |= USPosition;
+
+  if ((s = strchr(g + 1, '+')) == NULL && (s = strchr(g + 1, '-')) == NULL)
+    my_err(invalidGeom);
+  c = *s;
+  *s = '\0';
+  *x = make_int(g);
+
+  *s = c;
+  *y = make_int(s);
+}
